const { useState } = React;

function App() {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [bio, setBio] = useState("");
  const [errors, setErrors] = useState({});
  const [savedMessage, setSavedMessage] = useState("");

  function validate() {
    const newErrors = {};
    if (!fullName.trim()) newErrors.fullName = "Full name is required.";
    if (!email.trim()) newErrors.email = "Email is required.";
    return newErrors;
  }

  function handleSave(e) {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length === 0) {
      setSavedMessage("Profile saved.");
    } else {
      setSavedMessage("");
    }
  }

  function handleCancel() {
    setFullName("");
    setEmail("");
    setPhone("");
    setBio("");
    setErrors({});
    setSavedMessage("");
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fff;
          color: #222;
        }
        nav {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 0.75rem 1rem;
          border-bottom: 1px solid #ccc;
          background: #f9f9f9;
        }
        nav .logo {
          font-weight: 700;
          font-size: 1.25rem;
          user-select: none;
        }
        nav ul {
          list-style: none;
          display: flex;
          gap: 1.5rem;
          margin: 0;
          padding: 0;
          font-weight: 500;
          font-size: 1rem;
        }
        nav ul li {
          cursor: pointer;
          padding-bottom: 2px;
        }
        nav ul li.active {
          border-bottom: 2px solid #000;
          font-weight: 700;
        }
        main {
          max-width: 600px;
          margin: 2rem auto;
          padding: 0 1rem;
        }
        h1 {
          font-weight: 600;
          font-size: 1.5rem;
          margin-bottom: 1.5rem;
          user-select: none;
        }
        form {
          display: flex;
          flex-direction: column;
          gap: 1rem;
        }
        .profile-row {
          display: flex;
          gap: 1rem;
          align-items: flex-start;
        }
        .avatar {
          width: 80px;
          height: 80px;
          border-radius: 50%;
          background: #ddd;
          flex-shrink: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 700;
          font-size: 1.5rem;
          color: #888;
          user-select: none;
          border: 1px solid #bbb;
        }
        .inputs {
          flex-grow: 1;
          display: flex;
          flex-direction: column;
          gap: 0.75rem;
        }
        label {
          font-size: 0.875rem;
          font-weight: 600;
          margin-bottom: 0.25rem;
          user-select: none;
        }
        input[type="text"], input[type="email"], input[type="tel"], textarea {
          font-size: 1rem;
          padding: 0.5rem;
          border: 1px solid #ccc;
          border-radius: 4px;
          font-family: inherit;
          resize: vertical;
        }
        input[type="text"]:focus, input[type="email"]:focus, input[type="tel"]:focus, textarea:focus {
          outline: 2px solid #0078d4;
          border-color: #0078d4;
        }
        textarea {
          min-height: 80px;
          max-height: 160px;
        }
        .buttons {
          display: flex;
          gap: 1rem;
          margin-top: 0.5rem;
        }
        button {
          font-size: 1rem;
          padding: 0.5rem 1.25rem;
          border-radius: 20px;
          border: 1.5px solid #0078d4;
          background: #0078d4;
          color: white;
          cursor: pointer;
          font-weight: 600;
          transition: background-color 0.2s ease, color 0.2s ease;
          user-select: none;
        }
        button:hover {
          background: #005a9e;
          border-color: #005a9e;
        }
        button.cancel {
          background: white;
          color: #0078d4;
          border-color: #0078d4;
        }
        button.cancel:hover {
          background: #e6f0fa;
        }
        .error {
          color: #d93025;
          font-size: 0.875rem;
          margin-top: -0.5rem;
          margin-bottom: 0.5rem;
          user-select: none;
        }
        .saved-message {
          margin-top: 1rem;
          font-weight: 600;
          color: #2e7d32;
          user-select: none;
        }
      `}</style>

      <nav>
        <div className="logo" aria-label="Pulse logo">Pulse</div>
        <ul>
          <li className="active" tabIndex={0} aria-current="page">Home</li>
          <li tabIndex={0}>Profile</li>
        </ul>
      </nav>

      <main>
        <h1>Edit profile</h1>
        <form onSubmit={handleSave} noValidate>
          <div className="profile-row">
            <div className="avatar" aria-label="User avatar">X</div>
            <div className="inputs">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={fullName}
                onChange={e => setFullName(e.target.value)}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
                aria-invalid={errors.fullName ? "true" : "false"}
                required
              />
              {errors.fullName && (
                <div id="fullName-error" role="alert" className="error">
                  {errors.fullName}
                </div>
              )}

              <label htmlFor="email">Email</label>
              <input
                id="email"
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                aria-describedby={errors.email ? "email-error" : undefined}
                aria-invalid={errors.email ? "true" : "false"}
                required
              />
              {errors.email && (
                <div id="email-error" role="alert" className="error">
                  {errors.email}
                </div>
              )}

              <label htmlFor="phone">Phone</label>
              <input
                id="phone"
                type="tel"
                value={phone}
                onChange={e => setPhone(e.target.value)}
                aria-describedby={errors.phone ? "phone-error" : undefined}
                aria-invalid={errors.phone ? "true" : "false"}
              />
              {errors.phone && (
                <div id="phone-error" role="alert" className="error">
                  {errors.phone}
                </div>
              )}
            </div>
          </div>

          <label htmlFor="bio">Bio</label>
          <textarea
            id="bio"
            value={bio}
            onChange={e => setBio(e.target.value)}
            rows={4}
          />

          <div className="buttons">
            <button type="submit">Save</button>
            <button type="button" className="cancel" onClick={handleCancel}>
              Cancel
            </button>
          </div>

          {savedMessage && (
            <div role="alert" className="saved-message">
              {savedMessage}
            </div>
          )}
        </form>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

